import{_ as p,C as e,o as d,c,j as a,a as g,G as t,a2 as s}from"./chunks/framework.BgSoyxN5.js";const v=JSON.parse('{"title":"Требования к партнёрам TickerForge | Кто подходит, что нужно делать, когда доступ забирается","description":"Условия участия в партнёрской программе TickerForge: кто может стать партнёром, какие обязательства берёт на себя партнёр, раскрытие связи и точные причины, по которым партнёрский доступ ставится на паузу или заканчивается.","frontmatter":{"title":"Требования к партнёрам TickerForge | Кто подходит, что нужно делать, когда доступ забирается","description":"Условия участия в партнёрской программе TickerForge: кто может стать партнёром, какие обязательства берёт на себя партнёр, раскрытие связи и точные причины, по которым партнёрский доступ ставится на паузу или заканчивается.","aside":false,"locale":"ru","alternateLocales":{"en":"/partners/requirements","ru":"/ru/partners/requirements"},"pageClass":"partners-page"},"headers":[],"relativePath":"ru/partners/requirements.md","filePath":"ru/partners/requirements.md","lastUpdated":1788362384000}'),u={name:"ru/partners/requirements.md"},m={class:"partners-wide"};function h(_,r,f,b,T,P){const n=e("PartnerPageAnalytics"),i=e("PartnerCabinetCta"),l=e("PartnerReferralCta"),o=e("PartnerLeadForm");return d(),c("div",null,[r[0]||(r[0]=a("h1",{id:"требования-к-партнерам",tabindex:"-1"},[g("Требования к партнёрам "),a("a",{class:"header-anchor",href:"#требования-к-партнерам","aria-label":'Permalink to "Требования к партнёрам"'},"​")],-1)),r[1]||(r[1]=a("p",null,"Кто может стать партнёром TickerForge, что партнёр обязуется делать и когда партнёрский доступ заканчивается.",-1)),r[2]||(r[2]=a("p",null,"Партнёрская программа — это обмен, а не подарок. На этой странице обе стороны обмена написаны прямо: что даём мы, что просим взамен и из-за чего доступ прекращается.",-1)),t(n,{offer:"requirements",locale:"ru"}),r[3]||(r[3]=s('<div class="partners-hero-actions"><a class="partners-button partners-button--primary" href="#apply" data-partner-event="cta" data-partner-option="propose_pilot" data-analytics-placement="partner_hero">Подать заявку на пилот</a><a class="partners-button partners-button--secondary" href="#access-ends" data-partner-event="cta" data-partner-option="access_rules" data-analytics-placement="partner_hero">Когда доступ забирается</a></div><p class="partners-locale-switch"><a href="/partners/requirements" hreflang="en" data-partner-event="cta" data-partner-option="locale_en" data-analytics-placement="partner_locale_switch">Read this page in English</a></p><p class="partners-backlink"><a href="/ru/partners">Ко всем вариантам партнёрства</a> · <a href="/ru/partners/what-you-get">Что даём мы</a> · <a href="/ru/partners/stock-analysis-and-ideas">Исследования в Telegram</a> · <a href="/ru/partners/market-news">Рыночные новости</a> · <a href="/ru/partners/portfolio-health">Здоровье портфеля</a> · <a href="/ru/partners/cabinet">Partner Cabinet</a></p><p>Эта страница — про условия участия и жизненный цикл доступа. Форматы контента каждого направления перечислены на трёх страницах направлений.</p><p>TickerForge — образовательное программное обеспечение для поддержки решений. Это не инвестиционная рекомендация, не сигнальный канал, не брокер и не обещание доходности.</p><h2 id="benefits" tabindex="-1">🎁 Что получает партнёр <a class="header-anchor" href="#benefits" aria-label="Permalink to &quot;🎁 Что получает партнёр {#benefits}&quot;">​</a></h2><p>Те же пункты, что показывает раздел Partner Program внутри Telegram-бота.</p><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>⭐ Доступ Standard.</strong> TickerForge Standard на всё окно пилота, чтобы посты строились на полном исследовательском слое, а не на бесплатном публичном превью.</li><li><strong>🧠 Готовые исследования для постов.</strong> Живые Stock Verdict, активность инсайдеров, движения фондов и рыночный режим — то, что можно цитировать в своих материалах.</li><li><strong>🔗 Отслеживаемые ссылки.</strong> Каждый партнёрский пост может вести читателя сразу в нужный сценарий TickerForge через deep link в Telegram.</li><li><strong>💰 Реферальный доход.</strong> Читатели, привязанные по вашим партнёрским ссылкам, попадают в действующую реферальную программу и приносят доход по тем же правилам, что и <a href="/ambassador">/ambassador</a>.</li><li><strong>📊 Измеримый результат.</strong> Сгенерированные посты, отслеживаемые клики, рефералы и оценка заработка — в Партнёрском кабинете внутри бота.</li></ul></div><h2 id="eligibility" tabindex="-1">Кто может стать партнёром <a class="header-anchor" href="#eligibility" aria-label="Permalink to &quot;Кто может стать партнёром {#eligibility}&quot;">​</a></h2><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>Размер аудитории:</strong> от 1 000 живых подписчиков на основной площадке, где вы планируете публиковаться, — Telegram-канал, YouTube, Instagram, группа или страница в LinkedIn, рассылка, Discord, форумное сообщество.</li><li><strong>Живая аудитория:</strong> органические подписчики. Купленные подписчики, чаты активности и накрученные просмотры не подходят и в любой момент становятся причиной завершить пилот.</li><li><strong>Тематика:</strong> канал про инвестиции, рынки, личные финансы или разбор компаний. Контент TickerForge должен ложиться в то, что аудитория и так читает.</li><li><strong>Живой канал:</strong> минимум 3 месяца истории и регулярный ритм публикаций — примерно от 2 своих постов в месяц.</li><li><strong>Язык:</strong> сейчас поддерживаются англоязычная и русскоязычная аудитории. Другие языки — индивидуально.</li><li><strong>Telegram-аккаунт:</strong> при одобрении партнёрское место привязывается к одному Telegram-аккаунту, поэтому связь в Telegram нужна, даже если канал живёт на другой площадке.</li><li><strong>Совместимость по формулировкам:</strong> канал не продаёт торговые сигналы, не обещает доходность, не занимается копированием сделок и не рекламирует себя гарантиями прибыли.</li></ul></div><p><strong>Аудитории меньше порога.</strong> 1 000 — это значение по умолчанию, а не стена. Закрытый инвестклуб на 300 человек, консультант с реальной клиентской базой или нишевая рассылка с высокой открываемостью рассматриваются индивидуально. Присылайте цифры вовлечённости, а не только число подписчиков.</p><h2 id="commitments" tabindex="-1">Что обязуется делать партнёр <a class="header-anchor" href="#commitments" aria-label="Permalink to &quot;Что обязуется делать партнёр {#commitments}&quot;">​</a></h2><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>Объём публикаций:</strong> стандартный пилот — 3 качественных поста внутри 30-дневного окна доступа. Оба числа задаются индивидуально при одобрении и видны в Партнёрском кабинете как <em>Required posts</em>.</li><li><strong>Дальнейший ритм:</strong> если пилот продолжается, обычный ритм — 2–4 качественных поста в месяц.</li><li><strong>Засчитываются только подтверждённые посты.</strong> Кабинет отдельно показывает сгенерированные и подтверждённые посты. Сгенерировать пост в боте — не то же самое, что опубликовать его: в требование идут только опубликованные посты, которые мы можем подтвердить.</li><li><strong>Раскрытие связи:</strong> если пост рекламный, affiliate-supported или подготовлен с помощью бесплатного партнёрского доступа — скажите об этом так, как принято в вашем канале.</li><li><strong>Личное место:</strong> доступ принадлежит одобренному партнёру. Он не передаётся, не является командным аккаунтом, не раздаётся аудитории и не перепродаётся.</li><li><strong>Использование данных:</strong> вывод TickerForge — для ваших собственных постов. Публиковать его как отдельный фид, базу данных или конкурирующий продукт программа не предполагает.</li><li><strong>Формулировки:</strong> партнёрские посты остаются образовательными — рыночный контекст и аргументы, а не персональные рекомендации и обещания доходности. Правила те же, которым следует сам TickerForge.</li></ul></div><h3 id="что-считается-качественным-постом" tabindex="-1">Что считается качественным постом <a class="header-anchor" href="#что-считается-качественным-постом" aria-label="Permalink to &quot;Что считается качественным постом&quot;">​</a></h3><p>Пост засчитывается, когда выполнены все четыре условия:</p><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li>в нём есть <strong>реальная проверка TickerForge</strong> — настоящий блок с данными, скриншот или диагностика, которую вы прогнали, а не пересказ;</li><li>в нём сохранены <strong>ваш голос и ваш разбор</strong> — голый скриншот без комментария партнёрским постом не считается;</li><li>в нём есть <strong>понятный образовательный дисклеймер</strong>;</li><li>в нём есть <strong>отслеживаемая ссылка</strong> на бот или продуктовый сценарий, чтобы результат можно было измерить.</li></ul></div><h2 id="lifecycle" tabindex="-1">Как меняется статус партнёра <a class="header-anchor" href="#lifecycle" aria-label="Permalink to &quot;Как меняется статус партнёра {#lifecycle}&quot;">​</a></h2><div class="partners-wide partners-wide--timeline"><div class="partners-steps"><div><span>1</span><strong>Заявка</strong><p>Вы отправили форму. Доступ пока не выдан.</p></div><div><span>2</span><strong>Рассмотрение</strong><p>Смотрим канал, аудиторию, тематику и идею пилота.</p></div><div><span>3</span><strong>Активен</strong><p>Доступ Standard выдан на согласованное окно, кабинет открыт.</p></div><div><span>4</span><strong>Пауза</strong><p>Доступ прекращается сразу, по инициативе любой стороны, и может быть возобновлён.</p></div><div><span>5</span><strong>Истёк</strong><p>Окно закончилось. Доступ можно продлить или возобновить после разбора.</p></div></div></div><p>Партнёрский доступ ограничен по времени по замыслу и не продлевается автоматически. Продолжение — это решение, и оно опирается на то, что пилот реально дал.</p>',19)),t(i,{locale:"ru"}),r[4]||(r[4]=s('<h2 id="access-ends" tabindex="-1">Когда партнёрский доступ ставится на паузу или забирается <a class="header-anchor" href="#access-ends" aria-label="Permalink to &quot;Когда партнёрский доступ ставится на паузу или забирается {#access-ends}&quot;">​</a></h2><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>Закончилось окно.</strong> Период доступа истёк и не продлевается.</li><li><strong>Остановился ритм.</strong> Согласованное число подтверждённых постов не вышло в течение окна или прекратился месячный ритм.</li><li><strong>Посты не проходят по критериям.</strong> В публикациях нет реальной проверки, дисклеймера или отслеживаемой ссылки — подтвердить и измерить нечего.</li><li><strong>Доступом делятся.</strong> Доступ передан другому человеку, используется как командный или клиентский аккаунт, перепродаётся или раздаётся аудитории.</li><li><strong>Аудитория оказалась не той.</strong> Подписчики или вовлечённость оказались купленными либо накрученными.</li><li><strong>Нарушены формулировки.</strong> TickerForge подаётся как сигнальный сервис, гарантия прибыли, торговый робот или персональная рекомендация.</li><li><strong>Данные перепубликуются.</strong> Вывод продукта выкладывается как отдельный фид, база или конкурирующий продукт.</li><li><strong>Спам или фрод.</strong> Массовые нежелательные рассылки, накрутка трафика по отслеживаемым ссылкам, самоклики ради метрик пилота.</li><li><strong>Вы сами хотите остановиться.</strong> Партнёр может завершить пилот в любой момент, без штрафов и без объяснений.</li></ul></div><p>Во всём, кроме злоупотреблений, нормальный путь — сначала разговор: мы спрашиваем, что произошло, и ставим на паузу только если ритм действительно остановился. Пауза обратима: партнёра на паузе или с истёкшим доступом можно вернуть без повторной заявки с нуля.</p><h3 id="что-происходит-с-рефералами" tabindex="-1">Что происходит с рефералами <a class="header-anchor" href="#что-происходит-с-рефералами" aria-label="Permalink to &quot;Что происходит с рефералами&quot;">​</a></h3><p>Партнёрский доступ и реферальный доход — разные вещи, и потеря одного не стирает другое.</p><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>Уже привязанные читатели остаются вашими.</strong> Реферальная привязка работает по первому касанию и постоянна: она не переназначается после окончания пилота, и такие рефералы продолжают приносить доход по обычным правилам <a href="/ambassador">Ambassador</a>.</li><li><strong>Новые привязки прекращаются.</strong> Пока партнёрский доступ не активен, клики по партнёрским ссылкам больше не создают новых привязок.</li><li><strong>Первое касание выигрывает.</strong> Читатель, который уже закреплён за другим амбассадором, никогда не переприкрепляется к партнёрской ссылке.</li></ul></div>',6)),t(l,{eyebrow:"Реферальная программа",title:"Зарабатывайте на рекомендациях параллельно с пилотом",text:"Ambassador Program платит 20% от каждой платной подписки каждый месяц, пока приведённый пользователь остаётся активным. Это работает вместе с партнёрским пилотом: одна и та же аудитория может прийти по вашей отслеживаемой ссылке и оформить подписку по вашей реферальной.",note:"Страница программы пока доступна только на английском.",cta:"Посмотреть Ambassador Program"}),r[5]||(r[5]=s('<h2 id="not-included" tabindex="-1">Что не входит автоматически <a class="header-anchor" href="#not-included" aria-label="Permalink to &quot;Что не входит автоматически {#not-included}&quot;">​</a></h2><div class="partners-wide partners-wide--not"><p>Одобренный пилот даёт доступ Standard и ничего сверх него. Это отдельные коммерческие разговоры:</p><ul><li>доступ уровня Pro</li><li>bulk API и сырые фиды данных</li><li>кастомные и white-label отчёты</li><li>ко-брендинговые лендинги</li><li>платные размещения и рекламные бюджеты</li><li>эксклюзивность в нише или языке</li></ul><p>Всё это можно обсуждать после первого измеренного пилота — и часть из этого проще обосновать, когда уже есть реальные цифры.</p></div><h2 id="apply" tabindex="-1">Подать заявку на пилот <a class="header-anchor" href="#apply" aria-label="Permalink to &quot;Подать заявку на пилот {#apply}&quot;">​</a></h2><p>Расскажите про канал и про пилот, который хотите запустить. Чем больше деталей, тем быстрее рассмотрение: ссылка на канал или сообщество, размер аудитории и типичный охват поста, язык, основная тема, интересующее направление партнёрства, идея первого поста и хотите ли вы обсудить рекламные или affiliate-условия.</p>',4)),a("div",m,[t(o,{locale:"ru",source:"partners_requirements"})]),r[6]||(r[6]=s('<h2 id="смотрите-также" tabindex="-1">Смотрите также <a class="header-anchor" href="#смотрите-также" aria-label="Permalink to &quot;Смотрите также&quot;">​</a></h2><ul><li><a href="/ru/partners">Все варианты партнёрства</a></li><li><a href="/ru/partners/cabinet">Как работает Partner Cabinet</a></li><li><a href="/ru/partners/stock-analysis-and-ideas">Партнёрство: исследования в Telegram</a></li><li><a href="/ru/partners/market-news">Партнёрство: рыночные новости</a></li><li><a href="/ru/partners/portfolio-health">Партнёрство: здоровье портфеля</a></li><li><a href="/ru/partners/what-you-get">Что мы даём партнёру</a></li><li><a href="/ambassador">Реферальная программа Ambassador</a></li><li><a href="/pricing">Тарифы TickerForge</a></li></ul>',2))])}const q=p(u,[["render",h]]);export{v as __pageData,q as default};
